// machines/plaits: DX7's voice (engines/six_op.c voice_render after voice_setup), patch_unpack, op_env_set and
// six_op_render's buffer loops, hand-written SISD kernels.
// Generated by lib/gen_dx_kernel.py; do not edit by hand.
//
// dx_voice_kernel(SixOpVoice *v, float *temp, DxVoiceK *k): k holds the two divisions the C computes and the tables
//   (six_op.c, DxVoiceK); the kernel runs the scales, the pitch envelope, f0, the note-on, the six operators'
//   envelopes and levels (v->env[], v->level[]), writes render_ops' frequencies and amplitude increments into k, then
//   renders the algorithm's calls into temp's three buffers of `size` floats and updates v->phase[],
//   v->amplitude[] and v->feedback_state[].
//   Bit-identical to selcc's code of the C (-DPL_DX_C) (tests/plaits/test_dx_kernel.py).
//
// State on return: R0-R8, R12 and the flags change; every other register is as on entry (R9-R11, R13-R15 saved
// above I7; I0-I4, M4, M6, L0-L4 pushed through R0, M6 = 1 and L0-L4 = 0 set here). No SIMD.
// dx_pre_kernel(float *temp, const float *acc, int size): six_op_render's loops before voice_render:
//   temp[k] = acc[k] and temp[size + k] = 0.0f for k < size. R0, R2 and the flags change; I0, I1, M4, M6, L0, L1
//   pushed through R0.
// dx_post_kernel(float *temp, float *out, float *aux, float *acc, int size): the loops after it: out[k] = aux[k] =
//   SoftClip(temp[k] * 0.25f) (selcc's division) and acc[k] = temp[size + k]. R0-R8, R12 and the flags change;
//   R9-R11, R13, R14 saved above I7; I0-I3, M4, M6, L0-L3 pushed through R0.
// dx_unpack_kernel(SixOpPatch *p, const unsigned int *bank, int index): patch_unpack (fm::Patch::Unpack) of patch
//   `index` of the bank: the patch's 128 bytes into a frame row, then the fields. R0-R8 and the flags change; I0-I2,
//   M6, L0-L2 pushed through R0.
// dx_env_set_kernel(SixOpEnv *e, const SixOpPatchOp *op, int global_level): OperatorEnvelope::Set (op_env_set):
//   the four levels and increments, selcc's divisions. R0-R8 and the flags change; I0-I2, M4, L0-L2 pushed through R0.
// ABI: as the other kernels (lib/wavetable_sm.s). Assembled under .COMPRESS; integer additions in their 48-bit form.

.SECTION/PM seg_pmco;
.GLOBAL dx_voice_kernel.;
.GLOBAL dx_pre_kernel.;
.GLOBAL dx_post_kernel.;
.GLOBAL dx_unpack_kernel.;
.GLOBAL dx_env_set_kernel.;
.EXTERN pl_dx_op_level.;
.EXTERN pl_dx_op_increment.;
.EXTERN pl_lut_sine.;
.COMPRESS;

dx_voice_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = I2;
    DM(I7, M7) = R0;
    R0 = I3;
    DM(I7, M7) = R0;
    R0 = I4;
    DM(I7, M7) = R0;
    R0 = M4;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L2;
    DM(I7, M7) = R0;
    R0 = L3;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L2 = 0;
    L3 = 0;
    L4 = 0;
    I7=MODIFY (I7,-26)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I4 = R12;                                           // k
    I2 = R4;                                            // v
    DM(18, I7) = R4;
    DM(17, I7) = R8;
    R0 = 528;
    .NOCOMPRESS;
    R0 = R4 + R0;
    .COMPRESS;
    I0 = R0;                                            // &patch.op[0]
    R0 = 220;
    .NOCOMPRESS;
    R0 = R4 + R0;
    .COMPRESS;
    I1 = R0;                                            // &env[0]
    R0 = 212;
    .NOCOMPRESS;
    R0 = R4 + R0;
    .COMPRESS;
    DM(23, I7) = R0;                                    // &feedback_state[0]
    R0 = 36;
    .NOCOMPRESS;
    R0 = R12 + R0;
    .COMPRESS;
    DM(20, I7) = R0;                                    // &k->frequency[0]
    R1 = DM(0, I4);
    DM(13, I7) = R1;
    R1 = DM(1, I4);
    DM(14, I7) = R1;
    R11 = 0x4B000000;
    R1 = DM(2, I4);                                     // size
    DM(15, I7) = R1;
    R9 = PASS R1;                                       // envelope_rate = itof_nonneg(size)
    R1 = LSHIFT R1 BY 2;
    DM(16, I7) = R1;                                    // size in bytes
    R9 = R9 OR R11;                                     // itof_nonneg: (0x4B000000 | i) as a float - 8388608.0f
    F9 = F9 - F11;
    JUMP _dxv_pre;
_dxv_va:
    R1 = 3;
    .NOCOMPRESS;
    R6 = R3 + R1;  // level[(stage + 3) & 3]
    .COMPRESS;
    R6 = R6 AND R1;
    R1 = 7;
    .NOCOMPRESS;
    R6 = R6 + R1;
    .COMPRESS;
    M4 = R6;
    .NOCOMPRESS;
    R7 = R3 + R1;  // level[stage]
    .COMPRESS;
    R1 = 0xC2C80000;                                    // start == DX_PREVIOUS_LEVEL (-100.0f)
    COMP(F5, F1);
    .NOCOMPRESS;
    R6 = DM(M4, I1);
    .COMPRESS;
    M4 = R7;
    IF EQ R5 = R6 OR R6;                                // from
    R1 = 0x40D66666;                                    // 6.7f
    .NOCOMPRESS;
    R6 = DM(M4, I1);                                    // to
    .COMPRESS;
    COMP(F5, F6);                                       // if (reshape != 0 && from < to): selcc's IF GE skips
    IF GE JUMP _dxv_va2;
    R7 = DM(25, I7);
    R7 = PASS R7;
    IF EQ JUMP _dxv_va2;
    COMP(F1, F5);                                       // from = maxf(6.7f, from)
    IF GT R5 = R1 OR R1;
    COMP(F1, F6);                                       // to = maxf(6.7f, to)
    IF GT R6 = R1 OR R1;
    R1 = 0x40200000;                                    // phase *= (2.5f - phase) * 0.666667f
    F1 = F1 - F2;
    R7 = 0x3F2AAAB0;
    F1 = F1 * F7;
    F2 = F2 * F1;
_dxv_va2:
    F6 = F6 - F5;                                       // phase * (to - from) + from
    F6 = F2 * F6;
    F5 = F6 + F5;
    .NOCOMPRESS;
    RTS (DB);
    .COMPRESS;
    NOP;
    NOP;
_dxv_env:
    R3 = DM(0, I1);                                     // stage
    R1 = 3;
    R2 = 0;
    COMP(R14, R2);                                      // gate
    IF EQ JUMP _dxv_off;
    COMP(R3, R1);
    IF NE JUMP _dxv_go;
    R4 = 0;
    JUMP _dxv_tr;
_dxv_off:
    COMP(R3, R1);
    IF EQ JUMP _dxv_go;
    R4 = 3;
_dxv_tr:
    R2 = DM(1, I1);                                     // start = env_value_at(stage, phase, start)
    R5 = DM(2, I1);
    CALL _dxv_va;
    DM(2, I1) = R5;
    DM(0, I1) = R4;
    R3 = PASS R4;
    R2 = 0;
    DM(1, I1) = R2;                                     // phase = 0.0f
_dxv_go:
    R1 = 3;
    .NOCOMPRESS;
    R2 = R3 + R1;  // increment[stage]
    .COMPRESS;
    M4 = R2;
    R5 = DM(7, I7);
    R6 = DM(8, I7);
    COMP(R3, R1);                                       // stage == 3 ? release_scale : ad_scale
    IF EQ R5 = R6 OR R6;
    R2 = DM(1, I1);
    .NOCOMPRESS;
    R1 = DM(M4, I1);
    .COMPRESS;
    F1 = F1 * F0;                                       // phase += increment[stage] * rate * scale
    F1 = F1 * F5;
    F2 = F2 + F1;
    R5 = DM(2, I1);
    R1 = 0x3F800000;
    COMP(F2, F1);                                       // if (phase >= 1.0f): selcc's IF LT skips
    IF LT JUMP _dxv_nw;
    R1 = 2;
    COMP(R3, R1);                                       // stage >= 2: selcc's IF LT advances
    IF LT JUMP _dxv_adv;
    R2 = 0x3F800000;                                    // phase = 1.0f
    JUMP _dxv_st;
_dxv_adv:
    R2 = 0;                                             // phase = 0.0f, ++stage
    R1 = 1;
    .NOCOMPRESS;
    R3 = R3 + R1;
    .COMPRESS;
_dxv_st:
    R5 = 0xC2C80000;                                    // start = DX_PREVIOUS_LEVEL
_dxv_nw:
    DM(0, I1) = R3;
    DM(1, I1) = R2;
    DM(2, I1) = R5;
    CALL _dxv_va;                                       // env_value_at(stage, phase, start)
    .NOCOMPRESS;
    RTS (DB);
    .COMPRESS;
    NOP;
    NOP;
_dxv_p2:
    R1 = TRUNC F0;                                      // x_integral = (int)x
    R2 = 1;
    .NOCOMPRESS;
    R3 = R1 - R2;
    .COMPRESS;
    R2 = 0;
    COMP(F0, F2);                                       // if (x < 0.0f) --x_integral: selcc's IF GE skips
    IF LT R1 = R3 OR R3;
    R2 = R1 OR R11;                                     // itof_signed(x_integral)
    F2 = F2 - F11;
    R3 = -R1;
    R3 = R3 OR R11;
    F3 = F3 - F11;
    F3 = -F3;
    R4 = 0;
    COMP(R1, R4);
    IF LT R2 = R3 OR R3;
    F0 = F0 - F2;                                       // x -= itof_signed(x_integral)
    R2 = 0x3EAFDF3B;                                    // r = 1.0f + x * (0.6565f + x * 0.3435f)
    F2 = F0 * F2;
    R3 = 0x3F281062;
    F2 = F3 + F2;
    F2 = F0 * F2;
    R3 = 0x3F800000;
    F2 = F3 + F2;
    R1 = LSHIFT R1 BY 23;                               // float_bits(r) + (x_integral << 23)
    .NOCOMPRESS;
    R0 = R2 + R1;
    .COMPRESS;
    .NOCOMPRESS;
    RTS (DB);
    .COMPRESS;
    NOP;
    NOP;
_dxv_pre:
    R0 = DM(18, I2);                                    // ad_scale = pow2_fast_1((0.5f - envelope_control) * 8.0f)
    R1 = 0x3F000000;
    F1 = F1 - F0;
    R2 = 0x41000000;
    F1 = F1 * F2;
    R3 = 0x42FE0000;                                    // pow2_fast_1: (int)(8388608.0f * (127.0f + x))
    F1 = F3 + F1;
    F1 = F11 * F1;
    R1 = TRUNC F1;
    DM(7, I7) = R1;
    R1 = 0x3E99999A;                                    // r_scale = pow2_fast_1(-absf(envelope_control - 0.3f) * 8.0f)
    F1 = F0 - F1;
    F3 = -F1;
    R4 = 0;
    COMP(F1, F4);
    IF LT R1 = R3 OR R3;
    F1 = -F1;
    F1 = F1 * F2;
    R3 = 0x42FE0000;                                    // pow2_fast_1: (int)(8388608.0f * (127.0f + x))
    F1 = F3 + F1;
    F1 = F11 * F1;
    R1 = TRUNC F1;
    DM(8, I7) = R1;
    R14 = DM(14, I2);                                   // p_gate
    R0 = 0;
    DM(25, I7) = R0;
    R0 = 484;
    R8 = DM(18, I7);
    .NOCOMPRESS;
    R0 = R8 + R0;
    .COMPRESS;
    I1 = R0;                                            // &pitch_env
    R0 = PASS R9;
    CALL _dxv_env;                                      // pitch_envelope = env_render(&pitch_env, gate, envelope_rate, .., 0)
    R1 = DM(19, I2);                                    // pitch_mod = pitch_envelope + p_pitch_mod
    F5 = F5 + F1;
    R1 = DM(15, I2);                                    // p_note - 9.0f + pitch_mod * 12.0f
    R2 = 0x41100000;
    F1 = F1 - F2;
    R2 = 0x41400000;
    F5 = F5 * F2;
    F1 = F1 + F5;
    R2 = 0x3F800000;                                    // semitones_to_ratio_safe: scale
_dxv_s1:
    R3 = 0x42F00000;                                    // while (semitones > 120.0f)
    COMP(F1, F3);
    IF LE JUMP _dxv_s2;
    F1 = F1 - F3;
    R4 = 0x44800000;
    F2 = F2 * F4;
    JUMP _dxv_s1;
_dxv_s2:
    R3 = 0xC2F00000;                                    // while (semitones < -120.0f)
    COMP(F1, F3);
    IF GE JUMP _dxv_s3;
    R3 = 0x42F00000;
    F1 = F1 + F3;
    R4 = 0x3A800000;
    F2 = F2 * F4;
    JUMP _dxv_s2;
_dxv_s3:
    R3 = 0x43000000;                                    // SemitonesToRatio: pitch = semitones + 128.0f
    F1 = F1 + F3;
    R3 = TRUNC F1;
    R4 = R3 OR R11;
    F4 = F4 - F11;
    F1 = F1 - F4;                                       // pitch_fractional
    R4 = DM(6, I4);
    R5 = LSHIFT R3 BY 2;
    .NOCOMPRESS;
    R4 = R4 + R5;
    .COMPRESS;
    I3 = R4;                                            // &lut_pitch_ratio_high[pitch_integral]
    R5 = 0x43800000;
    F1 = F1 * F5;
    R1 = TRUNC F1;
    R5 = LSHIFT R1 BY 2;
    R4 = DM(7, I4);
    .NOCOMPRESS;
    R4 = R4 + R5;
    .COMPRESS;
    R3 = DM(0, I3);
    I3 = R4;                                            // &lut_pitch_ratio_low[(int)(pitch_fractional * 256.0f)]
    R5 = 0;                                             // (DAG gap)
    R6 = 0;
    R7 = 0;
    R4 = DM(0, I3);
    F3 = F3 * F4;
    F2 = F2 * F3;                                       // scale * SemitonesToRatio(semitones)
    R3 = 0x39962FC9;                                    // f0 = DX_A0 * 0.25f * ..
    F15 = F3 * F2;
    R0 = DM(2, I2);                                     // note_on = p_gate != 0 && gate_ == 0; gate_ = p_gate
    DM(2, I2) = R14;
    R1 = 0;
    COMP(R14, R1);
    IF EQ JUMP _dxv_non;
    COMP(R0, R1);
    IF NE JUMP _dxv_non;
    R0 = DM(16, I2);                                    // normalized_velocity = 16.0f * (Interpolate(lut_cube_root, velocity, 16.0f) - 0.918f)
    R1 = 0x41800000;
    F0 = F0 * F1;
    R1 = TRUNC F0;
    R2 = R1 OR R11;
    F2 = F2 - F11;
    F0 = F0 - F2;
    R2 = DM(8, I4);
    R3 = LSHIFT R1 BY 2;
    .NOCOMPRESS;
    R2 = R2 + R3;
    .COMPRESS;
    I3 = R2;
    R5 = 0;                                             // (DAG gap)
    R6 = 0;
    R7 = 0;
    R3 = DM(0, I3);
    R4 = DM(1, I3);
    F4 = F4 - F3;
    F4 = F4 * F0;
    F3 = F3 + F4;
    R4 = 0x3F6B020C;
    F3 = F3 - F4;
    R4 = 0x41800000;
    F3 = F4 * F3;
    DM(21, I2) = R3;
    R0 = DM(15, I2);                                    // note = p_note
    DM(22, I2) = R0;
    R0 = DM(268, I2);                                   // if (reset_phase) phase[] = 0
    R1 = 0;
    COMP(R0, R1);
    IF EQ JUMP _dxv_non;
    DM(23, I2) = R1;
    DM(24, I2) = R1;
    DM(25, I2) = R1;
    DM(26, I2) = R1;
    DM(27, I2) = R1;
    DM(28, I2) = R1;
_dxv_non:
    R0 = DM(22, I2);                                    // note
    DM(9, I7) = R0;
    R1 = 0x3EAAAA3B;                                    // note * 0.33333f - 7.0f
    F1 = F0 * F1;
    R2 = 0x40E00000;
    F10 = F1 - F2;
    R0 = DM(21, I2);
    DM(10, I7) = R0;
    R0 = DM(17, I2);                                    // (p_brightness - 0.5f) * 32.0f
    R1 = 0x3F000000;
    F0 = F0 - F1;
    R1 = 0x42000000;
    F0 = F0 * F1;
    DM(11, I7) = R0;
    R0 = DM(20, I2);                                    // p_amp_mod
    DM(12, I7) = R0;
    R0 = DM(266, I2);                                   // algorithm: modmask and the calls
    R2 = LSHIFT R0 BY 2;
    R1 = DM(4, I4);
    .NOCOMPRESS;
    R1 = R1 + R2;
    .COMPRESS;
    I3 = R1;
    R3 = LSHIFT R0 BY 3;
    .NOCOMPRESS;
    R4 = R3 + R3;
    .COMPRESS;
    .NOCOMPRESS;
    R4 = R4 + R3;
    .COMPRESS;
    R1 = DM(3, I4);
    R12 = DM(0, I3);                                    // modmask
    .NOCOMPRESS;
    R1 = R1 + R4;
    .COMPRESS;
    DM(19, I7) = R1;                                    // &pl_dx_calls[algorithm * 6]
    R1 = DM(5, I4);
    I3 = R1;                                            // lut_amp_mod
    R0 = DM(20, I7);
    I4 = R0;                                            // &k->frequency[0]
    R0 = 220;
    R8 = DM(18, I7);
    .NOCOMPRESS;
    R0 = R8 + R0;
    .COMPRESS;
    I1 = R0;                                            // &env[0]
    R0 = 1;
    DM(25, I7) = R0;                                    // operators: reshaped
    R13 = 6;
_dxv_op:
    R0 = DM(35, I2);                                    // ratios[i]
    R1 = PASS R15;
    R2 = 0xB7AEC33E;                                    // -DX_ONE_HZ
    R3 = 0;
    COMP(F0, F3);                                       // selcc: IF GE -> f0
    IF LT R1 = R2 OR R2;
    F0 = F0 * F1;                                       // f[i]
    R1 = 0x3F000000;
    COMP(F0, F1);                                       // minf(f[i], 0.5f)
    IF GE R0 = R1 OR R1;
    R1 = 0x4F800000;
    F0 = F0 * F1;                                       // * 4294967296.0f
    R2 = 0x4F000000;                                    // ftou
    F3 = F0 - F2;
    R3 = TRUNC F3;
    R4 = 0x80000000;
    .NOCOMPRESS;
    R3 = R3 + R4;
    .COMPRESS;
    R1 = TRUNC F0;
    COMP(F0, F2);
    IF GE R1 = R3 OR R3;
    DM(0, I4) = R1;                                     // k->frequency[i]
    R0 = DM(13, I0);
    R0 = R0 OR R11;                                     // itof_nonneg: (0x4B000000 | i) as a float - 8388608.0f
    F0 = F0 - F11;
    F0 = F0 * F10;
    R1 = 0x3D000000;
    F0 = F0 * F1;
    R1 = 0x42FE0000;                                    // pow2_fast_1: (int)(8388608.0f * (127.0f + x))
    F0 = F1 + F0;
    F0 = F11 * F0;
    R0 = TRUNC F0;
    F0 = F9 * F0;                                       // rate = envelope_rate * rate_scaling
    CALL _dxv_env;                                      // level = env_render(&env[i], gate, rate, ad_scale, release_scale, 1)
    R8 = PASS R5;                                       // level
    R0 = DM(8, I0);
    R0 = R0 OR R11;                                     // itof_nonneg: (0x4B000000 | i) as a float - 8388608.0f
    F0 = F0 - F11;
    R1 = DM(9, I7);
    F0 = F1 - F0;                                       // x = note - itof(break_point) - 15.0f
    R1 = 0x41700000;
    F0 = F0 - F1;
    R1 = DM(11, I0);
    R2 = DM(12, I0);
    R3 = DM(9, I0);
    R4 = DM(10, I0);
    R6 = 0;
    COMP(F0, F6);                                       // x > 0.0f ? right : left (curve and depth)
    IF GT R1 = R2 OR R2;
    COMP(F0, F6);                                       // (the select's OR wrote the flags)
    IF GT R3 = R4 OR R4;
    F2 = -F0;                                           // t = absf(x)
    COMP(F0, F6);
    IF GE R2 = R0 OR R0;
    R4 = 1;
    COMP(R1, R4);                                       // curve == 1 || curve == 2
    IF EQ JUMP _dxv_cube;
    R4 = 2;
    COMP(R1, R4);
    IF NE JUMP _dxv_nocube;
_dxv_cube:
    R4 = 0x3C2B7DC8;                                    // t = minf(t * 0.010467f, 1.0f)
    F2 = F2 * F4;
    R4 = 0x3F800000;
    COMP(F2, F4);
    IF GE R2 = R4 OR R4;
    F4 = F2 * F2;                                       // t = t * t * t
    F2 = F4 * F2;
    R4 = 0x42C00000;                                    // t *= 96.0f
    F2 = F2 * F4;
_dxv_nocube:
    F4 = -F2;                                           // if (curve < 2) t = -t
    R6 = 2;
    COMP(R1, R6);
    IF LT R2 = R4 OR R4;
    R3 = R3 OR R11;                                     // depth
    F3 = F3 - F11;
    F2 = F2 * F3;                                       // t * depth * 0.02677f
    R4 = 0x3CDB4CC2;
    F2 = F2 * F4;                                       // kb_scaling
    R0 = DM(15, I0);
    R0 = R0 OR R11;                                     // itof_nonneg: (0x4B000000 | i) as a float - 8388608.0f
    F0 = F0 - F11;
    R1 = DM(10, I7);
    F0 = F1 * F0;                                       // velocity_scaling = normalized_velocity * itof(velocity_sensitivity)
    F2 = F2 + F0;                                       // kb_scaling + velocity_scaling
    R0 = DM(14, I0);
    M4 = R0;                                            // lut_amp_mod index
    R1 = DM(11, I7);
    R4 = 0;
    R0 = 1;
    R0 = R12 AND R0;                                    // (modmask >> i) & 1 ? brightness : 0.0f
    IF EQ R1 = R4 OR R4;
    F2 = F2 + F1;
    R1 = DM(41, I2);
    COMP(F2, F1);                                       // boost = minf(.., level_headroom[i])
    IF GE R2 = R1 OR R1;
    R1 = 0x3E000000;
    F2 = F1 * F2;                                       // level += 0.125f * boost
